func main() {
	var n int
	fmt.Scan(&n)
	zones := make([]Interval, n)
	for i := range zones {
		fmt.Scan(&zones[i].Start, &zones[i].End)
	}

	sort.Slice(zones, func(i, j int) bool { return zones[i].Start < zones[j].Start })
	var closed []Interval
	for _, z := range zones {
		last := len(closed) - 1
		if last >= 0 && z.Start <= closed[last].End {
			if z.End > closed[last].End {
				closed[last].End = z.End
			}
		} else {
			closed = append(closed, z)
		}
	}

	for _, c := range closed {
		fmt.Printf("km %d to %d\n", c.Start, c.End)
	}
	fmt.Println("closed stretches:", len(closed))
}

