		var on, off, people int
		fmt.Scan(&on, &off, &people)
		events = append(events, Event{on, people}, Event{off, -people})
	}

	peak, peakStop := 0, 0
	sort.Slice(events, func(i, j int) bool {
		if events[i].Stop != events[j].Stop {
			return events[i].Stop < events[j].Stop
		}
		return events[i].Delta < events[j].Delta
