package main

import (
	"fmt"
	"sort"
)

type Interval struct{ Start, End int }

func main() {
	var n int
	fmt.Scan(&n)
	bookings := make([]Interval, n)
	for i := range bookings {
		fmt.Scan(&bookings[i].Start, &bookings[i].End)
	}

	sort.Slice(bookings, func(i, j int) bool { return bookings[i].End < bookings[j].End })
	var kept []Interval
	for _, b := range bookings {
		if len(kept) == 0 || b.Start >= kept[len(kept)-1].End {
			kept = append(kept, b)
		}
	}

	for _, k := range kept {
		fmt.Printf("keep %d to %d\n", k.Start, k.End)
	}
	fmt.Println("cancel", n-len(kept))
}

