import (
	"fmt"
	"sort"
)

type Interval struct{ Start, End int }

func main() {
	var n int
	fmt.Scan(&n)
	shows := make([]Interval, n)
	for i := range shows {
		fmt.Scan(&shows[i].Start, &shows[i].End)
	}

	watch := 0
	sort.Slice(shows, func(i, j int) bool { return shows[i].End < shows[j].End })
	lastEnd := 0
	for _, s := range shows {
		if watch == 0 || s.Start >= lastEnd {
			watch++
			lastEnd = s.End
		}
	}

	fmt.Printf("watch %d, skip %d\n", watch, n-watch)
}
